}

public static boolean computeWithTwoPointers(String s, String t) {
    int i = s.length() - 1;
    int j = t.length() - 1;

    while (i >= 0 || j >= 0) {
        i = getNextValidIndex(s, i);
        j = getNextValidIndex(t, j);

        if (i < 0 && j < 0) {
            return true;
        }
        if (i < 0 || j < 0) {
            return false;
        }
        if (s.charAt(i) != t.charAt(j)) {
            return false;
        }

        i--;
        j--;
    }
    return true;
}
